"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92138"],{24516(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.regra_tipo_invalido","status":422,"titulo":"A regra referenciada n\xe3o \xe9 do tipo esperado"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.regra_tipo_invalido","requisitos":[],"oQueAconteceu":["O c\xf3digo/vers\xe3o de uma das tr\xeas regras que a configura\xe7\xe3o de classifica\xe7\xe3o\\nreferencia \u2014 `regraCalculoCodigo`/`regraCalculoVersao`,\\n`regraArredondamentoCodigo`/`regraArredondamentoVersao` ou\\n`regraOrdemAlocacaoCodigo`/`regraOrdemAlocacaoVersao` \u2014 existe no\\n`rol_de_regras`, mas o tipo cadastrado da regra n\xe3o \xe9 o tipo que aquele\\ncampo espera (`REGRA_CALCULO`, `REGRA_ARREDONDAMENTO` ou\\n`REGRA_ORDEM_ALOCACAO`, respectivamente). O cat\xe1logo \xe9 compartilhado por\\nv\xe1rios tipos de regra do m\xf3dulo Sele\xe7\xe3o \u2014 o c\xf3digo sozinho n\xe3o garante o\\ntipo certo.","Roda logo depois de\\n[`regra_nao_encontrada`](/erros/uniplus.selecao.configuracao_classificacao.regra_nao_encontrada)\\nresolver a exist\xeancia de cada regra, no mesmo processamento sequencial \u2014\\nc\xe1lculo, depois arredondamento (se informado), depois ordem de aloca\xe7\xe3o. A\\nprimeira falha, de qualquer uma das duas causas em qualquer uma das tr\xeas\\nposi\xe7\xf5es, interrompe o processamento; nunca acumula com nenhuma outra causa\\ndesta s\xe9rie.","Este c\xf3digo tamb\xe9m \xe9 levantado, com o mesmo nome, para as regras de\\nelimina\xe7\xe3o \u2014 mas ali \xe9 uma causa pr\xf3pria de `RegraEliminacao` (ver\\n[`uniplus.selecao.regra_eliminacao.regra_tipo_invalido`](/erros/uniplus.selecao.regra_eliminacao.regra_tipo_invalido)),\\nn\xe3o esta."],"comoResolver":["Confirme, no cat\xe1logo de regras, que o c\xf3digo e a vers\xe3o declarados s\xe3o de\\nfato do tipo esperado para o campo em que foram informados. Se a inten\xe7\xe3o\\nera outra regra, reveja qual refer\xeancia pertence a qual campo do corpo do pedido."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);